<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { leaveApi } from '../api/leave'; import { useRouter } from 'vue-router'; import { statusLabel, statusType } from '../utils/status';
const router=useRouter(), loading=ref(false), rows=ref<any[]>([]), total=ref(0); const q=reactive({status:'',leaveType:'',startDate:'',endDate:'',page:0,size:10});
async function load(){loading.value=true;try{const r:any=await leaveApi.list(q);rows.value=r.data.items;total.value=r.data.total}finally{loading.value=false}}
async function action(id:number,type:'remove'|'submit'|'withdraw'){await ElMessageBox.confirm(type==='remove'?'确认删除草稿？':type==='submit'?'确认提交审批？':'确认撤回申请？','操作确认');await leaveApi[type](id);ElMessage.success('操作成功');load()}
onMounted(load)
</script>
<template><div class="page-title"><h1>请假申请</h1><p>创建并跟踪我的请假流程</p></div><el-card class="query"><el-form inline><el-form-item label="状态"><el-select v-model="q.status" clearable style="width:130px"><el-option label="草稿" value="DRAFT"/><el-option label="审批中" value="SUBMITTED"/><el-option label="已生效" value="EFFECTIVE"/><el-option label="已拒绝" value="REJECTED"/><el-option label="已撤回" value="CANCELLED"/></el-select></el-form-item><el-form-item label="类型"><el-select v-model="q.leaveType" clearable style="width:120px"><el-option label="年假" value="ANNUAL"/><el-option label="病假" value="SICK"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="q.page=0;load()">查询</el-button><el-button @click="router.push('/leave/new')">新建请假</el-button></el-form-item></el-form></el-card><el-card><el-table :data="rows" v-loading="loading" empty-text="暂无请假申请"><el-table-column prop="applicationNo" label="申请单号"/><el-table-column prop="leaveType" label="类型"/><el-table-column prop="startTime" label="开始时间"/><el-table-column prop="duration" label="时长(小时)"/><el-table-column label="状态"><template #default="s"><el-tag :type="statusType(s.row.businessStatus)">{{statusLabel(s.row.businessStatus)}}</el-tag></template></el-table-column><el-table-column label="操作" width="260"><template #default="s"><el-button link @click="router.push('/leave/'+s.row.id)">详情</el-button><el-button v-if="s.row.businessStatus==='DRAFT'" link @click="router.push('/leave/'+s.row.id+'/edit')">编辑</el-button><el-button v-if="s.row.businessStatus==='DRAFT'" link type="primary" @click="action(s.row.id,'submit')">提交</el-button><el-button v-if="s.row.businessStatus==='DRAFT'" link type="danger" @click="action(s.row.id,'remove')">删除</el-button><el-button v-if="s.row.businessStatus==='SUBMITTED'" link type="warning" @click="action(s.row.id,'withdraw')">撤回</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="q.page" :page-size="q.size" :total="total" @current-change="p=>{q.page=p-1;load()}"/></el-card></template>
